mapper.select:
SELECT m.message_id AS messageId, m.title AS title, m.content AS content, m.msg_type AS msgType, m.level AS level, m.link AS link, u.read_flag AS readFlag, u.read_time AS readTime, m.create_time AS createTime FROM sys_message_user u JOIN sys_message m ON m.message_id = u.message_id WHERE u.user_id = #{userId}
AND m.msg_type = #{query.msgType}
AND u.read_flag = #{query.readFlag}
AND m.title LIKE CONCAT('%', #{query.keyword}, '%')
ORDER BY m.message_id DESC
